:root { --paper: #f7f4ee; --card: #fffdf9; --ink: #211d18; --soft: #6d6459; --line: #e4ddd2; --clay: #b4552d; --moss: #5c6f52; }* { box-sizing: border-box; }body { background: var(--paper); color: var(--ink); margin: 0px; font: 15px / 1.6 system-ui, -apple-system, "Segoe UI", sans-serif; }h1, h2, .wordmark, .product-tile-name, .product-hero span { font-family: Georgia, "Times New Roman", serif; font-weight: 500; }a { color: inherit; }main { max-width: 1040px; margin: 0px auto; padding: 0px 24px 64px; }.site-header { justify-content: space-between; align-items: baseline; max-width: 1040px; margin: 0px auto; padding: 20px 24px; display: flex; }.wordmark { letter-spacing: 0.02em; font-size: 22px; text-decoration: none; }.site-header nav { gap: 20px; display: flex; }.site-header nav a { color: var(--soft); text-decoration: none; }.site-header nav a:hover { color: var(--ink); }.hero { max-width: 560px; padding: 48px 0px 40px; }.hero h1 { margin: 0px 0px 12px; font-size: 40px; line-height: 1.15; }.hero p { color: var(--soft); margin: 0px; }.product-grid { grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 28px 24px; display: grid; }.product-card { gap: 6px; text-decoration: none; display: grid; }.product-tile { aspect-ratio: 4 / 3; border-radius: 6px; align-items: flex-end; padding: 14px; display: flex; }.product-tile-name { color: rgba(255, 253, 249, 0.92); font-size: 19px; line-height: 1.2; }.product-meta { justify-content: space-between; font-weight: 600; display: flex; }.price { font-variant-numeric: tabular-nums; }.product-blurb { color: var(--soft); font-size: 13.5px; }.product-page { grid-template-columns: 1.1fr 1fr; gap: 40px; padding-top: 32px; display: grid; }@media (width <= 760px) {
  .product-page { grid-template-columns: 1fr; }
}.product-hero { border-radius: 8px; align-items: flex-end; min-height: 380px; padding: 22px; display: flex; }.product-hero span { color: rgba(255, 253, 249, 0.92); font-size: 28px; }.crumb { color: var(--soft); margin: 0px 0px 4px; font-size: 13px; }.product-info h1 { margin: 0px 0px 4px; font-size: 30px; }.price-lg { font-variant-numeric: tabular-nums; font-size: 20px; font-weight: 600; }.buy-row { align-items: flex-end; gap: 12px; margin: 20px 0px 10px; display: flex; }.buy-row label { color: var(--soft); gap: 4px; font-size: 13px; display: grid; }input[type="number"] { width: 64px; }input, button { font: inherit; }input { border: 1px solid var(--line); background: var(--card); border-radius: 5px; padding: 8px 10px; }input:focus { outline: 2px solid var(--moss); outline-offset: 1px; }.button-primary { background: var(--ink); color: var(--paper); cursor: pointer; border: none; border-radius: 5px; padding: 10px 20px; text-decoration: none; display: inline-block; }.button-primary:hover { background: rgb(58, 51, 43); }.button-quiet { border: 1px solid var(--line); cursor: pointer; color: var(--soft); background: 0px 0px; border-radius: 5px; padding: 8px 14px; }.button-quiet:hover { color: var(--ink); border-color: var(--soft); }.stock-row { align-items: center; gap: 12px; margin-top: 8px; display: flex; }.stock-note { color: var(--clay); font-size: 13.5px; }.page { max-width: 640px; padding-top: 40px; }.page h1 { margin: 0px 0px 16px; font-size: 30px; }.cart-list { border-top: 1px solid var(--line); margin: 0px; padding: 0px; list-style: none; }.cart-line { border-bottom: 1px solid var(--line); grid-template-columns: 44px 1fr 72px 72px auto; align-items: center; gap: 12px; padding: 14px 0px; display: grid; }.cart-swatch { border-radius: 4px; width: 44px; height: 34px; }.cart-name a { font-weight: 600; text-decoration: none; }.cart-price { text-align: right; font-variant-numeric: tabular-nums; }.cart-total { justify-content: space-between; align-items: baseline; padding: 18px 0px; display: flex; }.checkout-link { text-align: center; width: 100%; }.checkout-form { gap: 24px; display: grid; }fieldset { border: 1px solid var(--line); background: var(--card); border-radius: 8px; gap: 12px; padding: 16px 18px 18px; display: grid; }legend { color: var(--soft); padding: 0px 6px; font-size: 13px; }.checkout-form label { color: var(--soft); gap: 4px; font-size: 13.5px; display: grid; }.field-row { grid-template-columns: 1fr 1fr; gap: 12px; display: grid; }.coupon-row { grid-template-columns: 1fr auto; align-items: end; }.coupon-note { color: var(--moss); margin: 0px; font-size: 13.5px; }.order-summary { justify-content: space-between; align-items: baseline; display: flex; }.site-footer { border-top: 1px solid var(--line); flex-wrap: wrap; justify-content: space-between; gap: 32px; max-width: 1040px; margin: 0px auto; padding: 32px 24px 48px; display: flex; }.footer-title { margin: 0px 0px 4px; font-family: Georgia, serif; }.footer-note { color: var(--soft); margin: 0px; font-size: 13.5px; }.newsletter label { color: var(--soft); margin-bottom: 6px; font-size: 13px; display: block; }.newsletter-row { gap: 8px; display: flex; }
